import React, { useState, useRef } from 'react';
import {
  StyleSheet,
  Text,
  View,
  TouchableOpacity,
  SafeAreaView,
  Linking,
  Platform,
  ActivityIndicator,
  Alert,
} from 'react-native';
import { CameraView, useCameraPermissions } from 'expo-camera';
import { WebView } from 'react-native-webview';
import { StatusBar } from 'expo-status-bar';

// ---------------------------------------------------------------------------
// Expected QR code payload (JSON string), generated by generate_qr.py on the
// Raspberry Pi:
// {
//   "ssid": "RPI-Hotspot",
//   "password": "raspberry123",
//   "apiUrl": "http://192.168.4.1:5000",
//   "streamUrl": "http://192.168.4.1:8080/stream"
// }
//
// If the QR code is a *standard* Wi-Fi QR (WIFI:S:<ssid>;T:WPA;P:<pass>;;)
// we fall back to default apiUrl/streamUrl below, so it still works with
// a plain Wi-Fi QR generated by any tool.
// ---------------------------------------------------------------------------
const DEFAULT_API_URL = 'http://10.42.0.1:5000';
const DEFAULT_STREAM_URL = 'http://10.42.0.1:8080/stream';

const SCREENS = {
  SCAN: 'SCAN',
  CONNECT: 'CONNECT',
  STREAM: 'STREAM',
};

function parseQrData(raw) {
  // Try JSON payload first (custom format, recommended)
  try {
    const json = JSON.parse(raw);
    return {
      ssid: json.ssid ?? 'Unknown',
      password: json.password ?? '',
      apiUrl: json.apiUrl ?? DEFAULT_API_URL,
      streamUrl: json.streamUrl ?? DEFAULT_STREAM_URL,
    };
  } catch (e) {
    // Fall back to standard "WIFI:S:...;T:...;P:...;;" QR format
    if (raw.startsWith('WIFI:')) {
      const ssidMatch = raw.match(/S:([^;]*);/);
      const passMatch = raw.match(/P:([^;]*);/);
      return {
        ssid: ssidMatch ? ssidMatch[1] : 'Unknown',
        password: passMatch ? passMatch[1] : '',
        apiUrl: DEFAULT_API_URL,
        streamUrl: DEFAULT_STREAM_URL,
      };
    }
  }
  return null;
}

export default function App() {
  const [screen, setScreen] = useState(SCREENS.SCAN);
  const [connInfo, setConnInfo] = useState(null);
  const [permission, requestPermission] = useCameraPermissions();
  const [checkingApi, setCheckingApi] = useState(false);
  const scannedOnce = useRef(false);

  const handleBarcodeScanned = ({ data }) => {
    if (scannedOnce.current) return; // debounce multiple fires
    const parsed = parseQrData(data);
    if (!parsed) {
      Alert.alert(
        'Unrecognized QR code',
        'This QR code is not in the expected format for this demo.'
      );
      return;
    }
    scannedOnce.current = true;
    setConnInfo(parsed);
    setScreen(SCREENS.CONNECT);
  };

  const openWifiSettings = () => {
    if (Platform.OS === 'ios') {
      Linking.openURL('App-Prefs:root=WIFI').catch(() =>
        Linking.openSettings()
      );
    } else {
      Linking.sendIntent
        ? Linking.sendIntent('android.settings.WIFI_SETTINGS')
        : Linking.openSettings();
    }
  };

  const confirmConnectedAndGo = async () => {
    setCheckingApi(true);
    try {
      const res = await fetch(`${connInfo.apiUrl}/status`, {
        method: 'GET',
        timeout: 4000,
      });
      if (!res.ok) throw new Error('Bad response');
    } catch (e) {
      // Non-fatal: still let the user proceed, just warn them.
      Alert.alert(
        "Can't reach the Pi yet",
        `Make sure your phone is connected to "${connInfo.ssid}", then try again. You can still continue to the stream screen.`,
        [
          { text: 'Try Again', style: 'cancel' },
          { text: 'Continue Anyway', onPress: () => setScreen(SCREENS.STREAM) },
        ]
      );
      setCheckingApi(false);
      return;
    }
    setCheckingApi(false);
    setScreen(SCREENS.STREAM);
  };

  const restart = () => {
    scannedOnce.current = false;
    setConnInfo(null);
    setScreen(SCREENS.SCAN);
  };

  // --- SCAN SCREEN ---------------------------------------------------------
  if (screen === SCREENS.SCAN) {
    if (!permission) {
      return <View style={styles.center}><ActivityIndicator /></View>;
    }
    if (!permission.granted) {
      return (
        <SafeAreaView style={styles.center}>
          <Text style={styles.title}>Camera permission needed</Text>
          <Text style={styles.subtitle}>
            We need camera access to scan the Raspberry Pi's QR code.
          </Text>
          <TouchableOpacity style={styles.button} onPress={requestPermission}>
            <Text style={styles.buttonText}>Grant Permission</Text>
          </TouchableOpacity>
        </SafeAreaView>
      );
    }
    return (
      <View style={styles.flex}>
        <StatusBar style="light" />
        <CameraView
          style={styles.flex}
          barcodeScannerSettings={{ barcodeTypes: ['qr'] }}
          onBarcodeScanned={handleBarcodeScanned}
        />
        <View style={styles.scanOverlay}>
          <View style={styles.scanBox} />
          <Text style={styles.scanHint}>
            Point your camera at the QR code shown on the Raspberry Pi
          </Text>
        </View>
      </View>
    );
  }

  // --- CONNECT SCREEN ------------------------------------------------------
  if (screen === SCREENS.CONNECT) {
    return (
      <SafeAreaView style={styles.center}>
        <Text style={styles.title}>Pi Found</Text>
        <View style={styles.card}>
          <Text style={styles.cardLabel}>Network</Text>
          <Text style={styles.cardValue}>{connInfo.ssid}</Text>
          {!!connInfo.password && (
            <>
              <Text style={styles.cardLabel}>Password</Text>
              <Text style={styles.cardValue}>{connInfo.password}</Text>
            </>
          )}
        </View>
        <Text style={styles.subtitle}>
          Join this Wi-Fi network on your phone, then come back here.
        </Text>
        <TouchableOpacity style={styles.button} onPress={openWifiSettings}>
          <Text style={styles.buttonText}>Open Wi-Fi Settings</Text>
        </TouchableOpacity>
        <TouchableOpacity
          style={[styles.button, styles.buttonPrimary]}
          onPress={confirmConnectedAndGo}
          disabled={checkingApi}
        >
          {checkingApi ? (
            <ActivityIndicator color="#fff" />
          ) : (
            <Text style={styles.buttonText}>I'm Connected — View Camera</Text>
          )}
        </TouchableOpacity>
        <TouchableOpacity onPress={restart} style={styles.linkButton}>
          <Text style={styles.linkText}>Rescan QR code</Text>
        </TouchableOpacity>
      </SafeAreaView>
    );
  }

  // --- STREAM SCREEN ---------------------------------------------------------
  const streamHtml = `
    <html>
      <body style="margin:0;background:#000;">
        <img src="${connInfo.streamUrl}" style="width:100%;height:auto;display:block;" />
      </body>
    </html>
  `;
  return (
    <SafeAreaView style={styles.flex}>
      <StatusBar style="dark" />
      <View style={styles.streamHeader}>
        <Text style={styles.streamTitle}>Live Camera</Text>
        <TouchableOpacity onPress={restart}>
          <Text style={styles.linkText}>Rescan</Text>
        </TouchableOpacity>
      </View>
      <WebView
        source={{ html: streamHtml }}
        style={styles.flex}
        startInLoadingState
        renderLoading={() => (
          <View style={styles.center}>
            <ActivityIndicator size="large" />
          </View>
        )}
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  flex: { flex: 1 },
  center: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    padding: 24,
    backgroundColor: '#fff',
  },
  title: { fontSize: 22, fontWeight: '700', marginBottom: 8 },
  subtitle: {
    fontSize: 14,
    color: '#555',
    textAlign: 'center',
    marginBottom: 20,
  },
  button: {
    backgroundColor: '#eee',
    paddingVertical: 14,
    paddingHorizontal: 20,
    borderRadius: 10,
    marginTop: 10,
    width: '100%',
    alignItems: 'center',
  },
  buttonPrimary: { backgroundColor: '#1f6feb' },
  buttonText: { fontSize: 16, fontWeight: '600', color: '#111' },
  linkButton: { marginTop: 18 },
  linkText: { color: '#1f6feb', fontSize: 14, fontWeight: '600' },
  card: {
    width: '100%',
    backgroundColor: '#f5f5f5',
    borderRadius: 12,
    padding: 16,
    marginBottom: 16,
  },
  cardLabel: { fontSize: 12, color: '#888', marginTop: 6 },
  cardValue: { fontSize: 18, fontWeight: '600' },
  scanOverlay: {
    position: 'absolute',
    bottom: 0,
    left: 0,
    right: 0,
    alignItems: 'center',
    paddingBottom: 40,
  },
  scanBox: {
    width: 220,
    height: 220,
    borderWidth: 3,
    borderColor: '#fff',
    borderRadius: 16,
    marginBottom: 16,
  },
  scanHint: {
    color: '#fff',
    textAlign: 'center',
    paddingHorizontal: 30,
    fontSize: 13,
  },
  streamHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: 14,
    borderBottomWidth: 1,
    borderBottomColor: '#eee',
  },
  streamTitle: { fontSize: 18, fontWeight: '700' },
});
